-- generated by `python -m src.db --ddl` (sqlite)

CREATE TABLE bus (
	bus_id VARCHAR(64) NOT NULL, 
	label VARCHAR(128), 
	x FLOAT, 
	y FLOAT, 
	load_share FLOAT, 
	temp_offset_c FLOAT, 
	PRIMARY KEY (bus_id)
);

CREATE TABLE run (
	run_id INTEGER NOT NULL, 
	created_utc DATETIME NOT NULL, 
	label VARCHAR(128), 
	seed INTEGER, 
	config_json TEXT, 
	PRIMARY KEY (run_id)
);

CREATE TABLE generator (
	gen_id VARCHAR(64) NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	carrier VARCHAR(64), 
	p_nom_mw FLOAT, 
	marginal_cost FLOAT, 
	profile VARCHAR(64), 
	PRIMARY KEY (gen_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);

CREATE TABLE line (
	line_id VARCHAR(64) NOT NULL, 
	bus0 VARCHAR(64) NOT NULL, 
	bus1 VARCHAR(64) NOT NULL, 
	x_ohm FLOAT, 
	s_nom_mw FLOAT, 
	outage_rate FLOAT, 
	PRIMARY KEY (line_id), 
	FOREIGN KEY(bus0) REFERENCES bus (bus_id), 
	FOREIGN KEY(bus1) REFERENCES bus (bus_id)
);

CREATE TABLE lmp_quantile (
	run_id INTEGER NOT NULL, 
	source VARCHAR(64) NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	stat VARCHAR(16) NOT NULL, 
	value FLOAT, 
	PRIMARY KEY (run_id, source, bus_id, stat), 
	FOREIGN KEY(run_id) REFERENCES run (run_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);

CREATE TABLE runtime (
	run_id INTEGER NOT NULL, 
	method VARCHAR(128) NOT NULL, 
	seconds FLOAT, 
	PRIMARY KEY (run_id, method), 
	FOREIGN KEY(run_id) REFERENCES run (run_id)
);

CREATE TABLE scenario (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	hour_start DATETIME, 
	hour INTEGER, 
	dow INTEGER, 
	month INTEGER, 
	temp_system_c FLOAT, 
	cf_wind_south FLOAT, 
	cf_wind_central FLOAT, 
	cf_solar_south FLOAT, 
	pu_hydro FLOAT, 
	total_load_mw FLOAT, 
	merit_price FLOAT, 
	n_lines_out INTEGER, 
	gen_mw_on_outage FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id), 
	FOREIGN KEY(run_id) REFERENCES run (run_id)
);

CREATE TABLE surrogate_metric (
	run_id INTEGER NOT NULL, 
	task VARCHAR(16) NOT NULL, 
	model VARCHAR(64) NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	metric VARCHAR(64) NOT NULL, 
	value FLOAT, 
	PRIMARY KEY (run_id, task, model, bus_id, metric), 
	FOREIGN KEY(run_id) REFERENCES run (run_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);

CREATE TABLE bus_result (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	lmp FLOAT, 
	unserved_mw FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id, bus_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);

CREATE TABLE gen_dispatch (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	gen_id VARCHAR(64) NOT NULL, 
	p_mw FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id, gen_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(gen_id) REFERENCES generator (gen_id)
);

CREATE TABLE line_congestion_stat (
	run_id INTEGER NOT NULL, 
	source VARCHAR(64) NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	p_binding FLOAT, 
	ci95_low FLOAT, 
	ci95_high FLOAT, 
	expected_hours_per_year FLOAT, 
	PRIMARY KEY (run_id, source, line_id), 
	FOREIGN KEY(run_id) REFERENCES run (run_id), 
	FOREIGN KEY(line_id) REFERENCES line (line_id)
);

CREATE TABLE line_result (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	flow_mw FLOAT, 
	loading FLOAT, 
	binding BOOLEAN, 
	PRIMARY KEY (run_id, study, scenario_id, line_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(line_id) REFERENCES line (line_id)
);

CREATE TABLE n1_delta_lmp (
	run_id INTEGER NOT NULL, 
	outaged_line VARCHAR(64) NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	mean_delta_lmp FLOAT, 
	PRIMARY KEY (run_id, outaged_line, bus_id), 
	FOREIGN KEY(run_id) REFERENCES run (run_id), 
	FOREIGN KEY(outaged_line) REFERENCES line (line_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);

CREATE TABLE n1_result (
	run_id INTEGER NOT NULL, 
	outaged_line VARCHAR(64) NOT NULL, 
	islands VARCHAR(64), 
	share_hours_overload FLOAT, 
	max_post_loading FLOAT, 
	worst_line VARCHAR(64), 
	overload_mwh_per_year FLOAT, 
	islanded_injection_max_mw FLOAT, 
	delta_cost_musd_per_year FLOAT, 
	delta_congestion_rent_musd_per_year FLOAT, 
	mean_abs_delta_lmp FLOAT, 
	share_hours_lmp_changed_gt_1usd FLOAT, 
	unserved_mwh_per_year FLOAT, 
	rank_security INTEGER, 
	rank_economic INTEGER, 
	PRIMARY KEY (run_id, outaged_line), 
	FOREIGN KEY(run_id) REFERENCES run (run_id), 
	FOREIGN KEY(outaged_line) REFERENCES line (line_id)
);

CREATE TABLE scenario_bus_input (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	load_mw FLOAT, 
	temp_c FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id, bus_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);

CREATE TABLE scenario_gen_availability (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	gen_id VARCHAR(64) NOT NULL, 
	available_fraction FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id, gen_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(gen_id) REFERENCES generator (gen_id)
);

CREATE TABLE scenario_line_outage (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	PRIMARY KEY (run_id, study, scenario_id, line_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(line_id) REFERENCES line (line_id)
);

CREATE TABLE surrogate_congestion (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	p_binding FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id, line_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(line_id) REFERENCES line (line_id)
);

CREATE TABLE surrogate_lmp (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	model VARCHAR(64) NOT NULL, 
	bus_id VARCHAR(64) NOT NULL, 
	lmp_pred FLOAT, 
	PRIMARY KEY (run_id, study, scenario_id, model, bus_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(bus_id) REFERENCES bus (bus_id)
);
